import{_ as e,o as t,c as n,a3 as r}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"Jan のインストール","description":"Jan デスクトップアプリでローカルモデルをロードし、API を有効化して MiniTavern から LAN 接続。","frontmatter":{"title":"Jan のインストール","description":"Jan デスクトップアプリでローカルモデルをロードし、API を有効化して MiniTavern から LAN 接続。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"Jan のインストール · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Jan デスクトップアプリでローカルモデルをロードし、API を有効化して MiniTavern から LAN 接続。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/jan/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/jan/install"}]]},"headers":[],"relativePath":"ja/jan/install.md","filePath":"ja/jan/install.md","lastUpdated":1787224147000}'),i={name:"ja/jan/install.md"};function l(o,a,s,d,c,h){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="jan" tabindex="-1">Jan <a class="header-anchor" href="#jan" aria-label="Permalink to &quot;Jan&quot;">​</a></h1><p><a href="https://jan.ai/" target="_blank" rel="noreferrer">Jan</a> は「ローカル助手」寄りのデスクトップアプリで、モデルのダウンロード／ロードと、設定内の <strong>API Server</strong>（OpenAI 互換）により MiniTavern から接続できます。</p><h2 id="手順の要約" tabindex="-1">手順の要約 <a class="header-anchor" href="#手順の要約" aria-label="Permalink to &quot;手順の要約&quot;">​</a></h2><ol><li>Jan をインストールして開き、アプリ内でモデルを取得またはインポート。</li><li>設定の <strong>Local API</strong>／<strong>API Server</strong>（名称は現行バージョン準拠）を開く。</li><li>LAN アクセスを許可（スイッチがあれば）、<strong>ポート</strong>を控える。</li><li>本機で <code>http://127.0.0.1:ポート/v1/models</code> を開き一覧を確認。</li><li>スマホに <code>http://YOUR_PC_IP:ポート/v1</code>、モデル名は一覧と一致。</li></ol><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>Jan は版の更新が速い、メニュー経路は公式ドキュメント準拠。</li><li>つながらないときは先にサービスが Start 済みか、次にファイアウォールと IP（<a href="/ultra_guides/ja/troubleshoot">排錯</a>）。</li></ul><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><p><a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern での設定</a> · <a href="/ultra_guides/ja/local/tools">ツール一覧</a></p>',8)])])}const _=e(i,[["render",l]]);export{u as __pageData,_ as default};
